    int[] p0 = points[0];
    int[] p1 = points[1];
    int[] p2 = points[2];
    // Check for duplicate points
    if ((p0[0] == p1[0] && p0[1] == p1[1]) ||
        (p0[0] == p2[0] && p0[1] == p2[1]) ||
        (p1[0] == p2[0] && p1[1] == p2[1])) {
        return false;
    }
    // Check for collinearity using cross product
